import{_ as t,o,c as r,a2 as i}from"./chunks/framework.BXzK3EA4.js";const a="/assets/image%20(3)%20(1)%20(1)%20(1)%20(1)%20(1).CynwF39_.png",s="/assets/image%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1).BqHtM5gt.png",n="/assets/image%20(2)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1)%20(1).DUYoz-go.png",y=JSON.parse('{"title":"Paytm","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/paytm.md","filePath":"connect-brokers/brokers/paytm.md"}'),l={name:"connect-brokers/brokers/paytm.md"};function p(c,e,d,g,h,u){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="paytm" tabindex="-1">Paytm <a class="header-anchor" href="#paytm" aria-label="Permalink to &quot;Paytm&quot;">​</a></h1><p><strong>Paytm Money</strong> is a technology-first investment platform backed by one of India’s leading fintech companies. With its secure and scalable API infrastructure, Paytm Money empowers developers and traders to build powerful trading systems that can manage portfolios, place real-time orders, and stream live market data with ease. Whether you&#39;re building retail trading applications or complex algorithmic strategies, Paytm Money offers a reliable and developer-friendly gateway to the markets.</p><hr><h3 id="step-1-create-app" tabindex="-1">Step 1: Create App <a class="header-anchor" href="#step-1-create-app" aria-label="Permalink to &quot;Step 1: Create App&quot;">​</a></h3><ol><li><p>Go to <a href="https://developer.paytmmoney.com/" target="_blank" rel="noreferrer">Paytm Developer Portal</a></p></li><li><p>Click on <strong>Create New App</strong></p></li><li><p>Choose the following APIs:</p><ul><li><strong>Trading API</strong></li><li><strong>Live Broadcast API</strong> (optional, but recommended for real-time data)</li></ul><figure><img src="'+a+'" alt=""><figcaption></figcaption></figure></li><li><p>Click <strong>Proceed</strong></p></li></ol><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><hr><h3 id="step-2-enter-app-details" tabindex="-1">Step 2: Enter App Details <a class="header-anchor" href="#step-2-enter-app-details" aria-label="Permalink to &quot;Step 2: Enter App Details&quot;">​</a></h3><p>Fill out the app details as shown below:</p><ul><li><strong>App Name:</strong> <code>tradeboard</code></li><li><strong>Product Type:</strong> <code>Trading Bridge</code></li><li><strong>Redirect URL:</strong> <code>http://127.0.0.1:5000/paytm/callback</code></li><li><strong>Postback URL:</strong> <em>(leave empty)</em></li><li><strong>Description:</strong> <code>tradeboard</code></li><li>Upload a logo (optional)</li></ul><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><p>Click <strong>Create App</strong></p><hr><h3 id="step-3-copy-api-key-and-secret" tabindex="-1">Step 3: Copy API Key and Secret <a class="header-anchor" href="#step-3-copy-api-key-and-secret" aria-label="Permalink to &quot;Step 3: Copy API Key and Secret&quot;">​</a></h3><p>Once your app is in <strong>Active</strong> status:</p><ol><li>Go to <strong>My Apps</strong></li><li>Locate your app (e.g., <code>tradeboard</code>)</li><li>Copy the <strong>API Key</strong> and <strong>API Secret</strong></li></ol><figure><img src="'+a+`" alt=""><figcaption></figcaption></figure><p>Use these credentials in your Tradeboard broker configuration.</p><hr><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>Once you have the credentials, add them to your Tradeboard configuration:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BROKER_API_KEY = &#39;your_api_key_here&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BROKER_API_SECRET = &#39;your_api_secret_here&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REDIRECT_URL = &#39;http:</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">//127.0.0.1:5000/paytm/callback&#39;</span></span></code></pre></div><p>Make sure your local server is running and accessible at the callback URL you defined earlier.</p><hr><h4 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next?&quot;">​</a></h4><p>Integrating with the Paytm Money API opens the door to building high-performance, automated trading workflows within the Tradeboard ecosystem. To ensure seamless integration and performance, it’s essential to follow recommended practices such as securely storing your API credentials, managing session states effectively, and implementing robust logging and error-handling routines. With the right setup, Paytm Money becomes a dependable backbone for executing your trading strategies with precision and confidence.</p><hr><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/paytm/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code>, <code>BSE_INDEX</code></li></ul>`,30)])])}const f=t(l,[["render",p]]);export{y as __pageData,f as default};
